const HIS_MAX_DIAS = 93;

function _rutaHistorial(payload) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const usuario = _panSesion(ss, payload);
    if (!usuario) return { ok: false, codigo: "SESION_INVALIDA", mensaje: "Tu sesión venció. Ingresá de nuevo." };
    if (payload.accion === "hist_visitas") return _hisVisitas(ss, usuario, payload);
    if (payload.accion === "hist_asistencia") return _hisAsistencia(ss, usuario, payload);
    if (payload.accion === "hist_reconocimientos") return _hisReconocimientos(ss, usuario, payload);
    return { ok: false, codigo: "ACCION_INVALIDA", mensaje: "Acción no reconocida." };
  } catch (err) {
    _logError("Historial", payload.accion, "ERROR", String(err), String(err.stack || ""));
    return { ok: false, codigo: "ERROR_INTERNO", mensaje: "No se pudo procesar la consulta. Intentá de nuevo." };
  }
}

function _hisVisible(usuario, pais) {
  const paises = _panPaises(usuario, pais);
  const area = usuario.area;
  return (id, p) => {
    const pp = String(p || "").trim().toUpperCase();
    if (paises.indexOf(pp) < 0) return false;
    if (!area) return true;
    return area.ids.indexOf(String(id || "").trim().toUpperCase()) >= 0 || area.paisesBase.indexOf(pp) >= 0;
  };
}

function _hisSumar(fecha, dias) {
  return Utilities.formatDate(new Date(new Date(fecha + "T12:00:00Z").getTime() + dias * 86400000), "UTC", "yyyy-MM-dd");
}

function _hisRango(payload, diasBase) {
  const hoy = _formatFecha(new Date());
  const valida = v => /^\d{4}-\d{2}-\d{2}$/.test(String(v || ""));
  let hasta = valida(payload.hasta) ? String(payload.hasta) : hoy;
  let desde = valida(payload.desde) ? String(payload.desde) : _hisSumar(hasta, -diasBase);
  if (desde > hasta) {
    const t = desde;
    desde = hasta;
    hasta = t;
  }
  if (_hisSumar(desde, HIS_MAX_DIAS) < hasta) desde = _hisSumar(hasta, -HIS_MAX_DIAS);
  return { desde: desde, hasta: hasta };
}

function _hisVisita(f) {
  return {
    momento: f[0] instanceof Date ? f[0].toISOString() : "",
    fecha: _impTexto(f[1]),
    hora: _impHora(f[7]),
    id: String(f[2]).trim(),
    nombre: String(f[3]),
    pais: String(f[4]).trim().toUpperCase(),
    idTienda: String(f[5]),
    tienda: String(f[6]),
    origen: String(f[10] || ""),
    ubicacion: f[8] !== "" && f[8] !== null && f[8] !== undefined
  };
}

function _hisVisitas(ss, usuario, payload) {
  const rango = _hisRango(payload, 6);
  const visible = _hisVisible(usuario, payload.pais);
  const visitas = _impFilas(ss, IMP_VISITAS)
    .filter(f => f[2] && visible(f[2], f[4]))
    .map(_hisVisita)
    .filter(v => v.fecha >= rango.desde && v.fecha <= rango.hasta)
    .sort((a, b) => (a.fecha + " " + a.hora) < (b.fecha + " " + b.hora) ? 1 : -1);
  return { ok: true, codigo: "VISITAS_OK", desde: rango.desde, hasta: rango.hasta, visitas: visitas };
}

function _hisAsistencia(ss, usuario, payload) {
  const buscado = String(payload.id || "").trim().toUpperCase();
  const fila = _valoresHoja(ss, "Colaboradoras").slice(1).find(c => String(c[0]).trim().toUpperCase() === buscado);
  if (!buscado || !fila) return { ok: false, codigo: "NO_ENCONTRADA", mensaje: "No encontramos a esa persona." };
  const id = String(fila[0]);
  const pais = String(fila[1]).trim().toUpperCase();
  if (!_hisVisible(usuario, "")(id, pais)) return { ok: false, codigo: "SIN_PERMISO", mensaje: "Esa persona no está a tu cargo." };

  const hoy = _formatFecha(new Date());
  const actual = hoy.slice(0, 7);
  const pedido = String(payload.mes || "");
  const mes = /^\d{4}-\d{2}$/.test(pedido) && pedido <= actual ? pedido : actual;
  const desde = mes + "-01";
  const fin = Utilities.formatDate(new Date(Date.UTC(Number(mes.slice(0, 4)), Number(mes.slice(5, 7)), 0, 12)), "UTC", "yyyy-MM-dd");
  const hasta = fin < hoy ? fin : hoy;

  const base = _panDias(ss, desde, hasta, [pais], id);
  const persona = base.personas[id];
  const ctx = _alrContexto(ss);
  const decision = (fecha, tipo) => {
    const d = base.decisiones[fecha + "|" + id + "|" + tipo];
    return d ? d.decision : "";
  };

  const imprevistos = {};
  _impFilas(ss, IMP_HOJA).forEach(f => {
    const fecha = _impTexto(f[1]);
    if (String(f[2]).trim() !== id.trim() || fecha < desde || fecha > hasta || String(f[16]) === "Anulado") return;
    (imprevistos[fecha] = imprevistos[fecha] || []).push({
      tipo: IMP_TIPOS[String(f[7]).toUpperCase()] || String(f[7]),
      hora: _impHora(f[9]),
      regreso: _impHora(f[11]),
      destino: String(f[13] || ""),
      minutos: Number(f[15]) || 0,
      decision: String(f[18] || "")
    });
  });

  const visitas = {};
  _impFilas(ss, IMP_VISITAS).forEach(f => {
    if (String(f[2]).trim() !== id.trim()) return;
    const v = _hisVisita(f);
    if (v.fecha < desde || v.fecha > hasta) return;
    (visitas[v.fecha] = visitas[v.fecha] || []).push({ hora: v.hora, tienda: v.tienda });
  });

  const dias = (persona ? persona.dias : []).map(d => {
    const hb = d.horario || {};
    const marcas = (d.marcasLista || []).slice().sort((a, b) => a.momento < b.momento ? -1 : 1).map(m => ({
      tipo: m.tipo, hora: m.hora, tienda: ctx.porId[m.tienda] ? ctx.porId[m.tienda].nombre : ""
    }));
    return {
      fecha: d.fecha,
      estado: d.estado,
      es_hoy: d.fecha === hoy,
      cubierto: d.cubierto || "",
      tienda: hb.tienda || (marcas.length ? marcas[0].tienda : ""),
      entrada_programada: hb.entrada || "",
      salida_programada: hb.salida || "",
      marcas: marcas,
      tarde: d.tarde || 0,
      tarde_decision: d.tarde > 0 ? decision(d.fecha, "TARDANZA") : "",
      almuerzo: d.almuerzo,
      exceso_almuerzo: d.excesoAlmuerzo || 0,
      exceso_decision: d.excesoAlmuerzo > 0 ? decision(d.fecha, "ALMUERZO_EXCEDIDO") : "",
      ausencia_decision: d.ausente ? decision(d.fecha, "AUSENCIA") : "",
      sin_salida: !!d.sinSalida,
      minutos_trabajados: d.minutosTrabajados || 0,
      minutos_programados: d.minutosProgramados || 0,
      imprevistos: imprevistos[d.fecha] || [],
      visitas: (visitas[d.fecha] || []).sort((a, b) => a.hora < b.hora ? -1 : 1)
    };
  }).reverse();

  return {
    ok: true,
    codigo: "ASISTENCIA_OK",
    persona: { id: id, nombre: String(fila[2]), pais: pais, tienda: persona ? persona.tienda : "" },
    mes: mes,
    desde: desde,
    hasta: hasta,
    duracion_almuerzo_min: base.duracion,
    resumen: persona ? _panResumenPersona(persona) : null,
    dias: dias
  };
}

function _hisReconocimientos(ss, usuario, payload) {
  const hoja = ss.getSheetByName(OPT_RECONOCIMIENTOS);
  if (!hoja || hoja.getLastRow() < 2) return { ok: true, codigo: "RECONOCIMIENTOS_OK", meses: [] };
  const visible = _hisVisible(usuario, payload.pais);
  const grupos = {};
  hoja.getRange(2, 1, hoja.getLastRow() - 1, OPT_RECONOCIMIENTOS_COL.length).getValues().forEach(f => {
    const mes = f[0] instanceof Date ? Utilities.formatDate(f[0], "America/Costa_Rica", "yyyy-MM") : String(f[0]).trim().slice(0, 7);
    if (!/^\d{4}-\d{2}$/.test(mes) || !visible(f[2], f[1])) return;
    (grupos[mes] = grupos[mes] || []).push({
      id: String(f[2]).trim(),
      nombre: String(f[3]),
      pais: String(f[1]).trim().toUpperCase(),
      tienda: String(f[4]),
      trabajados: Number(f[5]) || 0,
      racha: Number(f[7]) || 0
    });
  });
  const meses = Object.keys(grupos).sort().reverse().map(m => ({
    mes: m,
    personas: grupos[m].sort((a, b) => b.trabajados - a.trabajados || a.nombre.localeCompare(b.nombre))
  }));
  return { ok: true, codigo: "RECONOCIMIENTOS_OK", meses: meses };
}
